import{_ as e,c as t,o as r,ag as o}from"./chunks/framework.C86mscM5.js";const h=JSON.parse('{"title":"Supabase","description":"","frontmatter":{},"headers":[],"relativePath":"server/baas/supabase/index.md","filePath":"server/baas/supabase/index.md","lastUpdated":1788689791000}'),s={name:"server/baas/supabase/index.md"};function n(l,a,i,p,c,d){return r(),t("div",null,a[0]||(a[0]=[o('<h1 id="supabase" tabindex="-1"><a href="https://supabase.com/" target="_blank" rel="nofollow noopener noreferrer">Supabase</a> <a class="header-anchor" href="#supabase" aria-label="Permalink to &quot;[Supabase](https://supabase.com/)&quot;">​</a></h1><p>Supabase 是一个基于 PostgreSQL 的后端平台，提供 BaaS（Backend as a Service，后端即服务）能力，将数据库、身份认证、文件存储、实时通信和服务端函数整合在一起，帮助开发者快速构建应用后端。</p><ul><li><a href="https://supabase.com/docs" target="_blank" rel="nofollow noopener noreferrer">官方文档</a></li></ul><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>Database</strong>：提供完整的 <strong>PostgreSQL</strong> 数据库，支持 SQL、扩展及自动生成的数据 API。</li><li><strong>Auth</strong>：提供用户注册、登录和身份管理，支持邮箱密码、无密码登录及 OAuth 等方式。</li><li><strong>Storage</strong>：存储和管理图片、视频、文档等文件，并通过访问策略控制权限。</li><li><strong>Realtime</strong>：订阅数据库变化、广播消息和同步在线状态，用于实时协作等场景。</li><li><strong>Edge Functions</strong>：运行服务端函数，处理自定义业务逻辑和第三方服务集成。</li></ul><h2 id="数据库连接模式" tabindex="-1">数据库连接模式 <a class="header-anchor" href="#数据库连接模式" aria-label="Permalink to &quot;数据库连接模式&quot;">​</a></h2><h3 id="连接池模式-transaction-pooling" tabindex="-1">连接池模式 Transaction Pooling <a class="header-anchor" href="#连接池模式-transaction-pooling" aria-label="Permalink to &quot;连接池模式 Transaction Pooling&quot;">​</a></h3>',7)]))}const b=e(s,[["render",n]]);export{h as __pageData,b as default};
